-- RRC155: one existing ingredient identity field only. Fresh dedicated strict MariaDB session.
DELIMITER //
BEGIN NOT ATOMIC
 DECLARE own_transaction BOOLEAN DEFAULT FALSE;
 DECLARE recipes_before BIGINT DEFAULT 0;
 DECLARE entries_before BIGINT DEFAULT 0;
 DECLARE locked_rows BIGINT DEFAULT 0;
 DECLARE changed_rows BIGINT DEFAULT 0;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN
  IF own_transaction THEN ROLLBACK; END IF;
  RESIGNAL;
 END;
 IF @@in_transaction<>0 OR DATABASE()<>'peq_housing_test' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC155 target/transaction mismatch'; END IF;
 IF FIND_IN_SET('STRICT_ALL_TABLES',@@SESSION.sql_mode)=0 AND FIND_IN_SET('STRICT_TRANS_TABLES',@@SESSION.sql_mode)=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC155 strict mode required'; END IF;
 IF(SELECT COUNT(*)FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE()AND TABLE_NAME IN('tradeskill_recipe','tradeskill_recipe_entries','items')AND ENGINE='InnoDB')<>3 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC155 InnoDB mismatch'; END IF;
 CREATE TEMPORARY TABLE rrc155_recipes LIKE tradeskill_recipe;
 CREATE TEMPORARY TABLE rrc155_before LIKE tradeskill_recipe_entries;
 CREATE TEMPORARY TABLE rrc155_after LIKE tradeskill_recipe_entries;
 INSERT INTO rrc155_recipes (`id`,`name`,`tradeskill`,`skillneeded`,`trivial`,`nofail`,`replace_container`,`notes`,`must_learn`,`learned_by_item_id`,`quest`,`enabled`,`min_expansion`,`max_expansion`,`content_flags`,`content_flags_disabled`) VALUES
(3785,CONVERT(0x426c6f6f646c696e6720506c6174652042656c74 USING utf8mb4),63,0,26,0,0,NULL,0,0,0,1,-1,-1,NULL,NULL);
 INSERT INTO rrc155_before (`id`,`recipe_id`,`item_id`,`successcount`,`failcount`,`componentcount`,`salvagecount`,`iscontainer`) VALUES
(38224,3785,12042,0,0,1,1,0),
(38225,3785,30523,0,0,1,1,0),
(38226,3785,30602,0,0,1,1,0),
(38227,3785,30652,1,0,0,0,0),
(38228,3785,17,0,0,0,0,1);
 INSERT INTO rrc155_after (`id`,`recipe_id`,`item_id`,`successcount`,`failcount`,`componentcount`,`salvagecount`,`iscontainer`) VALUES
(38224,3785,12042,0,0,1,1,0),
(38225,3785,30523,0,0,1,1,0),
(38226,3785,30664,0,0,1,1,0),
(38227,3785,30652,1,0,0,0,0),
(38228,3785,17,0,0,0,0,1);
 START TRANSACTION;
 SET own_transaction=TRUE;
 SELECT COUNT(*)INTO recipes_before FROM tradeskill_recipe;
 SELECT COUNT(*)INTO entries_before FROM tradeskill_recipe_entries;
 SELECT COUNT(*)INTO locked_rows FROM tradeskill_recipe r JOIN rrc155_recipes e ON r.id=e.id FOR UPDATE;
 IF locked_rows<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC155 definition/peer missing'; END IF;
 SELECT COUNT(*)INTO locked_rows FROM tradeskill_recipe_entries r JOIN rrc155_before e ON r.id=e.id FOR UPDATE;
 IF locked_rows<>5 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC155 target/peer entries missing'; END IF;
 IF EXISTS(SELECT 1 FROM rrc155_recipes e LEFT JOIN tradeskill_recipe r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND BINARY r.`name` <=> BINARY e.`name` AND r.`tradeskill` <=> e.`tradeskill` AND r.`skillneeded` <=> e.`skillneeded` AND r.`trivial` <=> e.`trivial` AND r.`nofail` <=> e.`nofail` AND r.`replace_container` <=> e.`replace_container` AND BINARY r.`notes` <=> BINARY e.`notes` AND r.`must_learn` <=> e.`must_learn` AND r.`learned_by_item_id` <=> e.`learned_by_item_id` AND r.`quest` <=> e.`quest` AND r.`enabled` <=> e.`enabled` AND r.`min_expansion` <=> e.`min_expansion` AND r.`max_expansion` <=> e.`max_expansion` AND BINARY r.`content_flags` <=> BINARY e.`content_flags` AND BINARY r.`content_flags_disabled` <=> BINARY e.`content_flags_disabled`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC155 definition/peer drift'; END IF;
 IF EXISTS(SELECT 1 FROM rrc155_before e LEFT JOIN tradeskill_recipe_entries r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer`)) OR(SELECT COUNT(*)FROM tradeskill_recipe_entries r JOIN rrc155_recipes p ON p.id=r.recipe_id)<>5 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC155 preimage mismatch'; END IF;
 IF(SELECT COUNT(*)FROM items WHERE (`id` <=> 12042 AND BINARY Name=BINARY CONVERT(0x42656c742053656374696f6e616c204d6f6c64 USING utf8mb4) AND `size` <=> 0 AND `itemclass` <=> 0 AND `itemtype` <=> 11 AND `stackable` <=> 0 AND `stacksize` <=> 1 AND `maxcharges` <=> 0 AND `bagtype` <=> 0 AND `bagslots` <=> 0 AND `bagsize` <=> 0 AND `classes` <=> 65535 AND `races` <=> 65535 AND `deity` <=> 0 AND `damage` <=> 0 AND `delay` <=> 0 AND `range` <=> 0 AND `slots` <=> 0 AND `purity` <=> 0 AND `augtype` <=> 0 AND `reqlevel` <=> 0 AND `reclevel` <=> 0 AND `loregroup` <=> 0 AND `filename` <=> '' AND `booktype` <=> 0) OR (`id` <=> 30523 AND BINARY Name=BINARY CONVERT(0x4e6570657461204f696c2045787472616374 USING utf8mb4) AND `size` <=> 1 AND `itemclass` <=> 0 AND `itemtype` <=> 38 AND `stackable` <=> 1 AND `stacksize` <=> 20 AND `maxcharges` <=> 0 AND `bagtype` <=> 0 AND `bagslots` <=> 0 AND `bagsize` <=> 0 AND `classes` <=> 65535 AND `races` <=> 65535 AND `deity` <=> 0 AND `damage` <=> 0 AND `delay` <=> 0 AND `range` <=> 0 AND `slots` <=> 0 AND `purity` <=> 0 AND `augtype` <=> 0 AND `reqlevel` <=> 0 AND `reclevel` <=> 0 AND `loregroup` <=> 0 AND `filename` <=> '' AND `booktype` <=> 0) OR (`id` <=> 30602 AND BINARY Name=BINARY CONVERT(0x426c6f6f646c696e67204361726170616365 USING utf8mb4) AND `size` <=> 1 AND `itemclass` <=> 0 AND `itemtype` <=> 11 AND `stackable` <=> 0 AND `stacksize` <=> 1 AND `maxcharges` <=> 0 AND `bagtype` <=> 0 AND `bagslots` <=> 0 AND `bagsize` <=> 0 AND `classes` <=> 65535 AND `races` <=> 65535 AND `deity` <=> 0 AND `damage` <=> 0 AND `delay` <=> 0 AND `range` <=> 0 AND `slots` <=> 0 AND `purity` <=> 0 AND `augtype` <=> 0 AND `reqlevel` <=> 0 AND `reclevel` <=> 0 AND `loregroup` <=> 0 AND `filename` <=> '' AND `booktype` <=> 0) OR (`id` <=> 30652 AND BINARY Name=BINARY CONVERT(0x426c6f6f646c696e6720506c6174652042656c74 USING utf8mb4) AND `size` <=> 1 AND `itemclass` <=> 0 AND `itemtype` <=> 10 AND `stackable` <=> 0 AND `stacksize` <=> 1 AND `maxcharges` <=> 0 AND `bagtype` <=> 0 AND `bagslots` <=> 0 AND `bagsize` <=> 0 AND `classes` <=> 33695 AND `races` <=> 61567 AND `deity` <=> 0 AND `damage` <=> 0 AND `delay` <=> 0 AND `range` <=> 0 AND `slots` <=> 1048576 AND `purity` <=> 0 AND `augtype` <=> 0 AND `reqlevel` <=> 0 AND `reclevel` <=> 0 AND `loregroup` <=> 0 AND `filename` <=> '' AND `booktype` <=> 0) OR (`id` <=> 30664 AND BINARY Name=BINARY CONVERT(0x426c6f6f646c696e6720436172617061636520506c617465 USING utf8mb4) AND `size` <=> 2 AND `itemclass` <=> 0 AND `itemtype` <=> 11 AND `stackable` <=> 0 AND `stacksize` <=> 1 AND `maxcharges` <=> 0 AND `bagtype` <=> 0 AND `bagslots` <=> 0 AND `bagsize` <=> 0 AND `classes` <=> 65535 AND `races` <=> 65535 AND `deity` <=> 0 AND `damage` <=> 0 AND `delay` <=> 0 AND `range` <=> 0 AND `slots` <=> 0 AND `purity` <=> 0 AND `augtype` <=> 0 AND `reqlevel` <=> 0 AND `reclevel` <=> 0 AND `loregroup` <=> 0 AND `filename` <=> '' AND `booktype` <=> 0))<>5 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC155 native item identity/range drift'; END IF;
 IF EXISTS(SELECT 1 FROM tradeskill_recipe_entries WHERE item_id=30652 AND successcount>0 AND iscontainer=0 AND recipe_id<>3785) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC155 output producer universe drift';END IF;
 IF(SELECT COUNT(DISTINCT a.recipe_id)FROM tradeskill_recipe_entries a WHERE a.item_id=30602 AND a.componentcount>0 AND a.iscontainer=0 AND(SELECT SUM(e.componentcount)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0)=3 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=12042)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=30523)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=30602)=1)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC155 full input universe drift';END IF;
 IF(SELECT COUNT(DISTINCT a.recipe_id)FROM tradeskill_recipe_entries a WHERE a.item_id=30664 AND a.componentcount>0 AND a.iscontainer=0 AND(SELECT SUM(e.componentcount)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0)=3 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=12042)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=30523)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=30664)=1)<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC155 full input universe drift';END IF;
 UPDATE tradeskill_recipe_entries r JOIN rrc155_after e ON r.id=e.id SET r.item_id=e.item_id WHERE r.id IN(38226);
 SET changed_rows=ROW_COUNT();
 IF changed_rows<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC155 changed-row mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM rrc155_recipes e LEFT JOIN tradeskill_recipe r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND BINARY r.`name` <=> BINARY e.`name` AND r.`tradeskill` <=> e.`tradeskill` AND r.`skillneeded` <=> e.`skillneeded` AND r.`trivial` <=> e.`trivial` AND r.`nofail` <=> e.`nofail` AND r.`replace_container` <=> e.`replace_container` AND BINARY r.`notes` <=> BINARY e.`notes` AND r.`must_learn` <=> e.`must_learn` AND r.`learned_by_item_id` <=> e.`learned_by_item_id` AND r.`quest` <=> e.`quest` AND r.`enabled` <=> e.`enabled` AND r.`min_expansion` <=> e.`min_expansion` AND r.`max_expansion` <=> e.`max_expansion` AND BINARY r.`content_flags` <=> BINARY e.`content_flags` AND BINARY r.`content_flags_disabled` <=> BINARY e.`content_flags_disabled`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC155 definition/peer drift'; END IF;
 IF EXISTS(SELECT 1 FROM rrc155_after e LEFT JOIN tradeskill_recipe_entries r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer`)) OR(SELECT COUNT(*)FROM tradeskill_recipe_entries r JOIN rrc155_recipes p ON p.id=r.recipe_id)<>5 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC155 postimage mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM tradeskill_recipe_entries WHERE item_id=30652 AND successcount>0 AND iscontainer=0 AND recipe_id<>3785) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC155 output producer universe drift';END IF;
 IF(SELECT COUNT(DISTINCT a.recipe_id)FROM tradeskill_recipe_entries a WHERE a.item_id=30664 AND a.componentcount>0 AND a.iscontainer=0 AND(SELECT SUM(e.componentcount)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0)=3 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=12042)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=30523)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=30664)=1)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC155 full input universe drift';END IF;
 IF(SELECT COUNT(DISTINCT a.recipe_id)FROM tradeskill_recipe_entries a WHERE a.item_id=30602 AND a.componentcount>0 AND a.iscontainer=0 AND(SELECT SUM(e.componentcount)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0)=3 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=12042)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=30523)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=a.recipe_id AND e.iscontainer=0 AND e.item_id=30602)=1)<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC155 full input universe drift';END IF;
 IF(SELECT COUNT(*)FROM tradeskill_recipe)<>recipes_before OR(SELECT COUNT(*)FROM tradeskill_recipe_entries)<>entries_before THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC155 global row-count drift'; END IF;
 DROP TEMPORARY TABLE rrc155_before;
 DROP TEMPORARY TABLE rrc155_after;
 DROP TEMPORARY TABLE rrc155_recipes;
 COMMIT;
 SET own_transaction=FALSE;
 SELECT 'RRC155',changed_rows,recipes_before,(SELECT COUNT(*)FROM tradeskill_recipe),entries_before,(SELECT COUNT(*)FROM tradeskill_recipe_entries),@@in_transaction;
END//
DELIMITER ;
